def modular_inverse(arr, N, P):
    """Return the number of elements among the first ``N`` whose modular inverse modulo ``P`` is itself.

    An element ``a`` is its own inverse modulo ``P`` exactly when
    ``(a * a) % P == 1``.
    """
    if P <= 0:
        return 0
    count = 0
    limit = len(arr) if N is None else min(N, len(arr))
    for index in range(limit):
        element = arr[index]
        if (element * element) % P == 1:
            count += 1
    return count
